function Testimonials() {
  const [start, setStart] = useState(0);
  const total = testimonials.length;
  const visible = [0, 1, 2].map((offset) => testimonials[(start + offset) % total]);

  return (
    <section className={`${wrap} pt-12`}>
      <SectionTitle>Lo que dicen nuestros clientes</SectionTitle>

      <div className="flex items-center gap-3">
        <button
          type="button"
          aria-label="Anterior"
          onClick={() => setStart((value) => (value - 1 + total) % total)}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-[var(--color-borde)] bg-[var(--color-tarjeta)] text-[var(--color-texto)] transition hover:bg-[var(--color-circulo)]"
        >
          <ChevronLeft size={16} />
        </button>

        <div className="grid flex-1 gap-4 md:grid-cols-2 lg:grid-cols-3">
          {visible.map((item, index) => (
            <figure
              key={`${item.name}-${index}`}
              className={`m-0 items-center gap-4 rounded-2xl border border-[var(--color-borde)] bg-[var(--color-tarjeta)] p-4 ${
                index === 0
                  ? "flex"
                  : index === 1
                    ? "hidden md:flex"
                    : "hidden lg:flex"
              }`}
            >
              <span className="flex h-14 w-14 shrink-0 items-center justify-center rounded-full bg-[var(--color-circulo)] text-lg font-bold text-[var(--color-circulo-icono)]">
                {item.name.charAt(0)}
              </span>
              <div>
                <p className="text-xs font-bold text-[var(--color-texto)]">
                  {item.name}
                </p>
                <Stars rating={5} />
                <blockquote className="m-0 mt-1 text-[11px] leading-4 text-[var(--color-texto-suave)]">
                  “{item.text}”
                </blockquote>
              </div>
            </figure>
          ))}
        </div>

        <button
          type="button"
          aria-label="Siguiente"
          onClick={() => setStart((value) => (value + 1) % total)}
          className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full border border-[var(--color-borde)] bg-[var(--color-tarjeta)] text-[var(--color-texto)] transition hover:bg-[var(--color-circulo)]"
        >
          <ChevronRight size={16} />
        </button>
      </div>
    </section>
  );
}


function BenefitsStrip() {
  return (
    <section className={`${wrap} pt-12`}>
      <div className="grid grid-cols-2 gap-5 rounded-2xl bg-[var(--color-activo-fondo)] px-6 py-6 md:grid-cols-4">
        {strip.map(({ icon: Icon, title, detail }) => (
          <div key={title} className="flex items-center gap-3">
            <Icon size={26} className="shrink-0 text-[var(--color-texto)]" />
            <div>
              <p className="text-xs font-bold text-[var(--color-texto)]">
                {title}
              </p>
              <p className="text-[10px] text-[var(--color-texto-suave)]">
                {detail}
              </p>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}

function Footer() {
  const [sent, setSent] = useState(false);

  return (
    <footer className="mt-12 border-t border-[var(--color-borde)] bg-[var(--color-footer)]">
      <div className={`${wrap} grid gap-10 py-12 lg:grid-cols-[1.2fr_repeat(3,0.8fr)_1.3fr]`}>
        <div>
          <p
            className={`${serif} m-0 text-3xl font-medium italic tracking-tight text-[var(--color-texto)]`}
          >
            Zentrall
          </p>
          <p className="mt-3 max-w-[14rem] text-xs leading-5 text-[var(--color-texto-suave)]">
            Productos y negocios locales seleccionados para el lugar que amas
            llamar hogar.
          </p>
          <div className="mt-4 flex gap-2">
            {["IG", "FB", "TT", "YT"].map((label) => (
              <span
                key={label}
                className="flex h-8 w-8 items-center justify-center rounded-full border border-[var(--color-borde)] text-[10px] font-bold text-[var(--color-texto)]"
              >
                {label}
              </span>
            ))}
          </div>
        </div>

        {footerColumns.map((column) => (
          <div key={column.title}>
            <h3 className="m-0 text-[11px] font-bold uppercase tracking-wider text-[var(--color-texto)]">
              {column.title}
            </h3>
            <ul className="mt-3 flex flex-col gap-2 p-0">
              {column.links.map((link) => (
                <li key={link} className="list-none">
                  <Link
                    href="/"
                    className="text-xs text-[var(--color-texto-suave)] transition hover:text-[var(--color-primario)]"
                  >
                    {link}
                  </Link>
                </li>
              ))}
            </ul>
          </div>
        ))}

        <div>
          <h3 className="m-0 text-[11px] font-bold uppercase tracking-wider text-[var(--color-texto)]">
            Mantente inspirado
          </h3>
          <p className="mt-3 text-xs leading-5 text-[var(--color-texto-suave)]">
            Suscríbete para recibir ofertas exclusivas, novedades y rutas para
            disfrutar la ciudad.
          </p>
          {sent ? (
            <p className="mt-3 text-xs font-semibold text-[var(--color-primario)]">
              ¡Gracias por suscribirte! 💌
            </p>
          ) : (
            <form
              onSubmit={(event) => {
                event.preventDefault();
                setSent(true);
              }}
              className="mt-3 flex overflow-hidden rounded-md border border-[var(--color-borde)] bg-[var(--color-superficie)]"
            >
              <input
                type="email"
                required
                aria-label="Correo electrónico"
                placeholder="Tu correo"
                className="min-w-0 flex-1 bg-transparent px-3 py-2.5 text-xs text-[var(--color-texto)] outline-none placeholder:text-[var(--color-texto-suave)]"
              />
              <button
                type="submit"
                className="bg-[var(--color-descuento)] px-4 text-[10px] font-bold uppercase tracking-wider text-white transition hover:opacity-90"
              >
                Suscribirme
              </button>
            </form>
          )}
          <div className="mt-4 flex flex-wrap gap-2">
            {["Visa", "Mastercard", "Transferencia", "Efectivo"].map((method) => (
              <span
                key={method}
                className="rounded border border-[var(--color-borde)] bg-[var(--color-tarjeta)] px-2 py-1 text-[9px] font-bold text-[var(--color-texto-suave)]"
              >
                {method}
              </span>
            ))}
          </div>
        </div>
      </div>

      <p className="border-t border-[var(--color-borde)] py-4 text-center text-[11px] text-[var(--color-texto-suave)]">
        © 2026 Zentrall. Todos los derechos reservados.
      </p>
    </footer>
  );
}

export function MarketplaceHomePage() {
  const [cartCount, setCartCount] = useState(0);
  const addToCart = () => setCartCount((value) => value + 1);

  return (
    <div className="min-w-0 bg-[var(--color-fondo)] text-[var(--color-texto)]">
      <AnnouncementBar />
      <Header cartCount={cartCount} />
      <main>
        <Hero />
        <OfferBanner />
        <Categories />
        <ProductSection
          title="Más vendidos"
          products={bestSellers}
          onAdd={addToCart}
        />
        <ProductSection
          title="Nuevas llegadas"
          products={newArrivals}
          isNew
          onAdd={addToCart}
        />
        <PromoBanners />
        <Testimonials />
        <BenefitsStrip />
      </main>
      <Footer />
    </div>
  );
}